//! On-demand prices per region (RULES 121): `data/prices/<provider>/<region>.csv`, one file for each
//! region of AWS, Azure and GCP, generated by `scripts/gen-instances.mjs` and embedded. The cost
//! estimate reads a type's price in the region the person picked; the default-region price also
//! sits in `data/instances.csv` ([`crate::instances::Instance::price_micro_usd_hr`]).
//!
//! **Every price is an estimate**: the on-demand Linux list price an hour, in micro-USD (1,000,000
//! = 1 dollar, an integer so sums do not drift), as the catalogue carried it on the date in the
//! file header. Reserved and spot prices, Windows, egress, storage and managed-service fees are not
//! here. A type with no price in a region is absent from that region's file.

use std::sync::OnceLock;

use crate::prices_data::FILES;

/// A default region per provider (what `data/instances.csv` carries): AWS `us-east-1`, Azure
/// `us-east` (East US), GCP `us-central1`.
pub const DEFAULT_REGIONS: [(&str, &str); 3] = [
    ("aws", "us-east-1"),
    ("azure", "us-east"),
    ("gcp", "us-central1"),
];

/// A parsed region file: `(type name, micro-USD an hour)`, sorted by name.
type Prices = Vec<(&'static str, u32)>;

/// Every region file, parsed on first use, in the order of [`FILES`].
fn parsed() -> &'static [OnceLock<Prices>] {
    static CELLS: OnceLock<Vec<OnceLock<Prices>>> = OnceLock::new();
    CELLS.get_or_init(|| FILES.iter().map(|_| OnceLock::new()).collect())
}

/// The regions of `provider` (`aws`, `azure` or `gcp`), sorted.
#[must_use]
pub fn regions(provider: &str) -> Vec<&'static str> {
    FILES
        .iter()
        .filter(|(p, _, _)| *p == provider)
        .map(|(_, r, _)| *r)
        .collect()
}

/// The prices of `region` of `provider`, sorted by type name (`provider/type`, lower case); `None`
/// for a region the table does not have.
#[must_use]
pub fn region_table(provider: &str, region: &str) -> Option<&'static [(&'static str, u32)]> {
    let i = FILES
        .iter()
        .position(|(p, r, _)| *p == provider && *r == region)?;
    let table = parsed()[i].get_or_init(|| {
        FILES[i]
            .2
            .lines()
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .map(|l| {
                let (name, price) = l.split_once(',').expect("a name and a price");
                (name, price.parse().expect("the price is a number"))
            })
            .collect()
    });
    Some(table)
}

/// The price an hour of the type `name` (`aws/m5.large`) in `region`, in micro-USD; `None` when the
/// region is not the provider's, or the type has no price there.
#[must_use]
pub fn price_micro_usd_hr(region: &str, name: &str) -> Option<u32> {
    let key = name.trim().to_ascii_lowercase();
    let provider = key.split_once('/')?.0;
    let table = region_table(provider, region)?;
    table
        .binary_search_by(|(n, _)| (*n).cmp(key.as_str()))
        .ok()
        .map(|i| table[i].1)
}
